#!/usr/bin/env python3
# =============================================================================
# ANGELA-MATRIX: [L3] [βγ] [B] [L2]
# LAYER: learning
# =============================================================================
"""§92: the same counterfactual, with the oracle generated by a grammar.

§91.9 measured a coverage bias: 123/248 hold-out rows were selectable, but only
8/34 and 6/35 of the *correct* rows fell inside them — 26 and 29 correct rows sat
in families the hand-written hypothesis list could not fit. The verdict was
`underpowered`, and the registered rule forbids relaxing the power floor.

This module keeps §91's measurement and decision rule, and replaces only the
hypothesis list: instead of 26 hand-written expressions, the candidates are
generated from a grammar (operands in prompt order, `+ - * / % **`, nesting
depth <= 2, plus a constant scale solved from the corpus). Nothing is
hand-tuned per family: a family either has exactly one distinct fit or it is
dropped and counted.

Two deliberate differences from §91, both declared in §92 before any scored run:

* **equivalent fits are one fit, and every fit must agree on the perturbed row.**
  A candidate counts as a fit only if it reproduces every training row's gold at
  two decimals, so two fits can never disagree at that resolution: the data
  cannot tell them apart, and "drop the family because two expressions fit"
  would throw away usable rows for a distinction the corpus does not contain.
  Instead the guard moves to the test point: the perturbed row is scored only if
  *every* fitting candidate agrees on its value there.
* **the constant scale is solved per family**, so `/2`, `/100` and `*9.8` are
  the same mechanism: `gold = k * expr`, with `k` required to be constant across
  all rows of the family.

Everything is diagnostic: no training, no checkpoint changes, no thresholds.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import sys
import time
from pathlib import Path
from typing import Any, Dict, List, Optional, Sequence, Tuple

REPO_ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(REPO_ROOT / "apps" / "backend" / "src"))
sys.path.insert(0, str(REPO_ROOT / "scripts"))

import probe_core_counterfactual as base  # noqa: E402
from probe_core_callers import measure_holdout, rows_digest, sha256_file  # noqa: E402
from probe_core_recipe_ab import load_model  # noqa: E402
from train_token_snn import read_pairs  # noqa: E402

DATA = REPO_ROOT / "apps" / "backend" / "data"
PROCESSED = DATA / "processed"
TRAIN = PROCESSED / "distill_train.jsonl"
HOLDOUT = PROCESSED / "distill_val_holdout.jsonl"
CHECKPOINTS = REPO_ROOT / "data" / "e2_recipe_ab" / "final_epoch" / "checkpoints"
OUT_DIR = REPO_ROOT / "data" / "e4_grammar"

ARMS: Tuple[Tuple[str, int], ...] = (("snn", 0), ("snn", 1), ("gru", 0), ("gru", 1))
DECIDING_ARM = "snn"

#: §92 — carried over from §91 unchanged, so the two runs are comparable.
MIN_FAMILY_ROWS = 8
MIN_CORRECT = 10
BUMP_LADDER: Tuple[int, ...] = (1, 2, 3, 4)
MULTIPLE_LADDER: Tuple[int, ...] = (1, 2, 3, 4, 5)
MAX_NON_NUMERIC_SHARE = 0.05
CONTROL_ROWS = 60

BINARY_OPS: Tuple[str, ...] = ("+", "-", "*", "/", "%", "**")
#: commutative operators get one operand order (the reversed one is the same fit)
SYMMETRIC = ("+", "*")

Node = Tuple[Any, ...]


# -- the grammar (§92.1) ----------------------------------------------------
def _op(op: str, left: Node, right: Node) -> Node:
    return ("op", op, left, right)


def _x(index: int) -> Tuple[str, int]:
    return ("x", index)


def name_of(node: Node) -> str:
    """A readable name; distinct trees print differently (nested parts wrapped)."""
    tag = node[0]
    if tag == "x":
        return f"x{node[1]}"
    if tag == "scale":
        return f"{node[1]:g}*{_part(node[2])}"
    _, op, left, right = node
    return f"{_part(left)}{op}{_part(right)}"


def _part(node: Node) -> str:
    return name_of(node) if node[0] == "x" else f"({name_of(node)})"


def build_candidates(width: int) -> List[Node]:
    """Every node the grammar allows for ``width`` operands, in a fixed order.

    The grammar is the implementation of §92.1; it is not adjusted per family.
    Operands may repeat (``x0*x0*x1`` is kinetic energy), and symmetric
    operators keep a single operand order.
    """
    xs = [_x(i) for i in range(width)]
    out: List[Node] = list(xs)

    for op in BINARY_OPS:
        for left in xs:
            for right in xs:
                if op in SYMMETRIC and left[1] > right[1]:
                    continue
                out.append(_op(op, left, right))

    # Shapes are generated even when ``width`` is smaller than the number of
    # leaves: an expression may use the same operand twice (kinetic energy is
    # ``0.5 * m * v * v``, and a two-slot family has no third operand to spend).
    if width >= 2:
        for op1 in ("+", "-", "*", "/"):
            for op2 in ("+", "-"):
                for i in range(width):
                    for j in range(width):
                        for k in range(width):
                            out.append(_op(op2, _op(op1, xs[i], xs[j]), xs[k]))
                            out.append(_op(op1, xs[i], _op(op2, xs[j], xs[k])))
        for op1 in ("+", "-"):
            for op2 in ("*", "/"):
                for i in range(width):
                    for j in range(width):
                        for k in range(width):
                            out.append(_op(op2, _op(op1, xs[i], xs[j]), xs[k]))
                            out.append(_op(op1, xs[i], _op(op2, xs[j], xs[k])))
        for op1 in ("+", "-"):
            for i in range(width):
                for j in range(width):
                    for k in range(width):
                        out.append(_op("*", xs[i], _op(op1, xs[j], xs[k])))
        for i in range(width):
            for j in range(width):
                for k in range(width):
                    out.append(_op("*", _op("*", xs[i], xs[j]), xs[k]))
                    out.append(_op("/", _op("*", xs[i], xs[j]), xs[k]))
                    out.append(_op("/", xs[i], _op("*", xs[j], xs[k])))

    if width >= 4:
        for i in range(width):
            for j in range(width):
                for k in range(width):
                    for m in range(width):
                        out.append(_op("*", _op("*", xs[i], xs[j]), _op("*", xs[k], xs[m])))
    return out


def evaluate(node: Node, x: Sequence[float]) -> Optional[float]:
    try:
        tag = node[0]
        if tag == "x":
            return float(x[node[1]])
        if tag == "scale":
            inner = evaluate(node[2], x)
            return None if inner is None else float(node[1]) * inner
        _, op, left, right = node
        a = evaluate(left, x)
        b = evaluate(right, x)
        if a is None or b is None:
            return None
        if op == "+":
            value = a + b
        elif op == "-":
            value = a - b
        elif op == "*":
            value = a * b
        elif op == "/":
            value = a / b
        elif op == "%":
            value = math.fmod(a, b)
        elif op == "**":
            if abs(b) > 12 or (abs(a) > 1e4 and b > 2):
                return None
            value = a**b
        else:  # pragma: no cover - the grammar has no other operator
            return None
    except (ZeroDivisionError, OverflowError, ValueError):
        return None
    if not math.isfinite(value) or abs(value) > 1e18:
        return None
    return float(value)


def as_node(value: Any) -> Node:
    """Tuples for a node that has round-tripped through JSON."""
    if isinstance(value, list):
        return tuple(as_node(item) for item in value)
    return value


# -- fitting (§92.2) --------------------------------------------------------
def _constant_scale(values: Sequence[float], golds: Sequence[float]) -> Optional[float]:
    ratios: List[float] = []
    for value, gold in zip(values, golds):
        if abs(value) <= 1e-12:
            return None
        ratios.append(gold / value)
    if not ratios:
        return None
    first = ratios[0]
    if any(abs(r - first) > 1e-6 * max(1.0, abs(first)) for r in ratios):
        return None
    return first


def fit_family(rows: Sequence[Tuple[str, str]], width: int) -> Dict[str, Any]:
    """Fit one digit-template family; drop it unless one distinct fit remains."""
    parsed = [(base.slot_values(prompt), base.numeric_gold(gold)) for prompt, gold in rows]
    numeric = [(slots, gold) for slots, gold in parsed if gold is not None]
    non_numeric = len(parsed) - len(numeric)
    if not numeric:
        return {"status": "no-numeric-gold", "non_numeric": non_numeric}
    if non_numeric / len(parsed) > MAX_NON_NUMERIC_SHARE:
        return {
            "status": "too-many-non-numeric",
            "non_numeric": non_numeric,
            "rows": len(parsed),
        }

    constant = sorted({i for i in range(width) if len({s[i] for s, _ in numeric}) == 1})
    keep = [i for i in range(width) if i not in constant]
    if not keep:
        return {"status": "no-operands", "non_numeric": non_numeric}
    if len(keep) > 4:
        return {"status": "too-many-operands", "operands": len(keep)}
    operands = [[float(slots[i]) for i in keep] for slots, _ in numeric]
    golds = [gold for _, gold in numeric]

    fits: List[Tuple[Node, str, Tuple[float, ...]]] = []
    for node in build_candidates(len(keep)):
        values = [evaluate(node, x) for x in operands]
        if any(value is None for value in values):
            continue
        scaled = [float(v) for v in values]
        # k = 1 first: a modulo family has a varying gold/value ratio, so solving
        # the scale before this check would silently drop it.
        if not all(base._agrees(value, f"{gold}") for value, gold in zip(scaled, golds)):
            scale = _constant_scale(scaled, golds)
            if scale is None or abs(scale - 1.0) <= 1e-9:
                continue
            scaled = [scale * value for value in scaled]
            if not all(base._agrees(value, f"{gold}") for value, gold in zip(scaled, golds)):
                continue
            node = ("scale", scale, node)
        fits.append((node, name_of(node), tuple(round(v, 9) for v in scaled)))

    if not fits:
        return {
            "status": "no-expression",
            "constant_slots": constant,
            "operands": len(keep),
            "non_numeric": non_numeric,
        }

    # Group at the resolution a fit is judged at (2 decimals). Two fits therefore
    # cannot land in different groups; if they somehow do, the family is dropped
    # and counted rather than guessed.
    groups: Dict[Tuple[float, ...], List[Tuple[Node, str]]] = {}
    for node, name, _vector in fits:
        values = [evaluate(node, x) for x in operands]
        key = tuple(round(float(value), 2) for value in values)
        groups.setdefault(key, []).append((node, name))
    if len(groups) > 1:
        return {
            "status": "inconsistent-fit",
            "groups": len(groups),
            "constant_slots": constant,
            "operands": len(keep),
            "non_numeric": non_numeric,
        }
    members = next(iter(groups.values()))
    unique: Dict[str, Node] = {}
    for node, name in members:
        unique.setdefault(name, node)
    ordered = sorted(unique.items(), key=lambda item: (len(item[0]), item[0]))
    return {
        "status": "usable",
        "node": ordered[0][1],
        "expression": ordered[0][0],
        "nodes": [node for _, node in ordered],
        "equivalent": len(ordered),
        "constant_slots": constant,
        "operands": len(keep),
        "non_numeric": non_numeric,
    }


# -- perturbation (§92.3) ---------------------------------------------------
def perturb(
    prompt: str,
    family: Dict[str, Any],
    bump_ladder: Sequence[int],
    multiple_ladder: Sequence[int],
    train_prompts: set,
) -> Optional[Dict[str, Any]]:
    """Same guards as §91; the ladder may move any single operand.

    §91 could only bump the first operand (differences need one side moved) or
    the numerator of a pure ratio. A grammar expression can depend on any
    operand, so every single-operand move is tried, in order, before giving up.
    """
    slots = base.slot_values(prompt)
    keep = [i for i in range(len(slots)) if i not in family["constant_slots"]]
    x = [float(slots[i]) for i in keep]
    node = as_node(family["node"])
    expression = family["expression"]
    gold_before = evaluate(node, x)
    if gold_before is None:
        return None
    gold_is_integer = abs(gold_before - round(gold_before)) <= 1e-9
    others = [as_node(node) for node in family.get("nodes") or [family["node"]]]

    strategies: List[str] = []
    if node[0] == "op" and node[1] == "/" and node[2][0] == "x" and node[3][0] == "x":
        strategies.append("numerator")
    strategies += ["all"] + [f"only:{index}" for index in range(len(x))]

    for strategy in strategies:
        for step in multiple_ladder if strategy == "numerator" else bump_ladder:
            new_slots = list(slots)
            if strategy == "numerator":
                numerator, denominator = node[2][1], node[3][1]
                moved = x[:]
                moved[numerator] = x[numerator] + step * x[denominator]
                new_x = moved
            elif strategy == "all":
                bumped = [base._bump(slots[keep[i]], value, step) for i, value in enumerate(x)]
                if any(value is None for value in bumped):
                    continue
                new_x = [float(value) for value in bumped]
            else:
                index = int(strategy.split(":")[1])
                one = base._bump(slots[keep[index]], x[index], step)
                if one is None:
                    continue
                new_x = list(x)
                new_x[index] = float(one)
            for position, value in zip(keep, new_x):
                new_slots[position] = base._format_like(slots[position], value)
            text = base._rewrite(prompt, new_slots)
            if text in train_prompts:
                continue
            gold_after = evaluate(node, new_x)
            if gold_after is None or abs(gold_after - gold_before) <= 1e-9:
                continue
            if (abs(gold_after - round(gold_after)) <= 1e-9) != gold_is_integer:
                continue
            # every candidate that fits the training rows must agree here too,
            # otherwise the "truth" for this test point depends on which
            # expression I happened to pick.
            if any(
                (evaluate(other, new_x) is None)
                or not base._agrees(evaluate(other, new_x), f"{gold_after}")
                for other in others
            ):
                continue
            return {
                "q": text,
                "gold": base._gold_text(gold_after, gold_before),
                "step": step,
                "strategy": strategy,
                "expression": expression,
            }
    return None


# -- measurement ------------------------------------------------------------
def build_families(train: Sequence[Tuple[str, str]]) -> Dict[str, Dict[str, Any]]:
    grouped: Dict[str, List[Tuple[str, str]]] = {}
    for prompt, answer in train:
        grouped.setdefault(base.digit_template(prompt), []).append((prompt, answer))
    families: Dict[str, Dict[str, Any]] = {}
    for template, rows in grouped.items():
        if len(rows) < MIN_FAMILY_ROWS:
            continue
        widths = {len(base.slot_values(prompt)) for prompt, _ in rows}
        if len(widths) != 1:
            families[template] = {"rows": rows, "n": len(rows), "status": "ragged-slots"}
            continue
        # ``fit`` first: the "too-many-non-numeric" status carries a row *count*
        # under "rows", which would otherwise replace the row list with an int
        # (no §92 family had that status, so §92's numbers are unaffected).
        families[template] = {
            **fit_family(rows, widths.pop()),
            "n": len(rows),
            "rows": rows,
        }
    return families


def select_rows(
    pairs: Sequence[Tuple[str, str]], families: Dict[str, Dict[str, Any]]
) -> Tuple[List[Dict[str, Any]], Dict[str, int]]:
    train_prompts = {q for family in families.values() for q, _ in family["rows"]}
    selected: List[Dict[str, Any]] = []
    dropped: Dict[str, int] = {}
    for index, (prompt, gold) in enumerate(pairs):
        template = base.digit_template(prompt)
        family = families.get(template)
        if family is None or family.get("status") != "usable":
            dropped["family-not-usable"] = dropped.get("family-not-usable", 0) + 1
            continue
        moved = perturb(prompt, family, BUMP_LADDER, MULTIPLE_LADDER, train_prompts)
        if moved is None:
            dropped["no-perturbation"] = dropped.get("no-perturbation", 0) + 1
            continue
        selected.append(
            {
                "i": index,
                "template": template,
                "expression": moved["expression"],
                "node": family["node"],
                "constant_slots": list(family["constant_slots"]),
                "q": prompt,
                "gold": gold,
                "q_cf": moved["q"],
                "gold_cf": moved["gold"],
                "step": moved["step"],
                "strategy": moved["strategy"],
            }
        )
    return selected, dropped


def _score(rows: Sequence[Dict[str, Any]]) -> Dict[str, Any]:
    correct = sum(1 for row in rows if row["exact_raw"])
    return {
        "n": len(rows),
        "correct": correct,
        "rate": round(correct / len(rows), 4) if rows else 0.0,
        "answered": sum(1 for row in rows if row["answered"]),
    }


def run_arm(
    kind: str,
    seed: int,
    selected: Sequence[Dict[str, Any]],
    control: Sequence[Dict[str, Any]],
) -> Dict[str, Any]:
    path = CHECKPOINTS / f"{kind}_seed{seed}.pt"
    model = load_model(kind, path)
    started = time.time()
    original = measure_holdout(model, [(row["q"], row["gold"]) for row in selected])
    counterfactual = measure_holdout(model, [(row["q_cf"], row["gold_cf"]) for row in selected])
    control_original = measure_holdout(model, [(row["q"], row["gold"]) for row in control])
    control_counterfactual = measure_holdout(
        model, [(row["q_cf"], row["gold_cf"]) for row in control]
    )
    by_family: Dict[str, Dict[str, Any]] = {}
    for row, before, after in zip(selected, original, counterfactual):
        cell = by_family.setdefault(
            row["expression"],
            {"n": 0, "original": 0, "counterfactual": 0, "changed": 0},
        )
        cell["n"] += 1
        cell["original"] += int(before["exact_raw"])
        cell["counterfactual"] += int(after["exact_raw"])
        cell["changed"] += int(before["answer"].strip() != after["answer"].strip())
    changed = sum(
        1
        for before, after in zip(original, counterfactual)
        if before["answer"].strip() != after["answer"].strip()
    )
    return {
        "arm": kind,
        "seed": seed,
        "checkpoint": str(path.relative_to(REPO_ROOT)),
        "sha256": sha256_file(path),
        "seconds": round(time.time() - started, 1),
        "original": _score(original),
        "counterfactual": _score(counterfactual),
        "answer_changed": {"n": len(selected), "changed": changed},
        "control_original": _score(control_original),
        "control_counterfactual": _score(control_counterfactual),
        "by_expression": by_family,
        "rows": [
            {
                "i": row["i"],
                "template": row["template"],
                "expression": row["expression"],
                "node": row["node"],
                "constant_slots": row["constant_slots"],
                "strategy": row["strategy"],
                "q": row["q"],
                "gold": row["gold"],
                "answer": before["answer"],
                "correct": before["exact_raw"],
                "q_cf": row["q_cf"],
                "gold_cf": row["gold_cf"],
                "answer_cf": after["answer"],
                "correct_cf": after["exact_raw"],
                "step": row["step"],
            }
            for row, before, after in zip(selected, original, counterfactual)
        ],
    }


def verdict(runs: Sequence[Dict[str, Any]]) -> Dict[str, Any]:
    deciding = [run for run in runs if run["arm"] == DECIDING_ARM]
    if not deciding:
        return {"verdict": "not-decided-missing-arm", "arm": DECIDING_ARM}
    results: List[Dict[str, Any]] = []
    for run in deciding:
        original = int(run["original"]["correct"])
        counter = int(run["counterfactual"]["correct"])
        if original < MIN_CORRECT:
            label = "underpowered"
        elif counter >= max(5, 0.5 * original):
            label = "computes"
        elif counter < 0.25 * original:
            label = "imitates"
        else:
            label = "mixed"
        results.append(
            {
                "seed": run["seed"],
                "original": original,
                "counterfactual": counter,
                "n": run["original"]["n"],
                "label": label,
            }
        )
    labels = {cell["label"] for cell in results}
    if labels == {"computes"}:
        overall = "computes"
    elif labels == {"imitates"}:
        overall = "imitates"
    elif "underpowered" in labels:
        overall = "underpowered"
    else:
        overall = "mixed"
    return {
        "verdict": overall,
        "arm": DECIDING_ARM,
        "per_seed": results,
        "rule": {
            "computes": "counterfactual >= max(5, 50% of original), every deciding seed",
            "imitates": "counterfactual < 25% of original, every deciding seed",
            "mixed": "between the two",
            "underpowered": f"fewer than {MIN_CORRECT} correct original rows",
        },
    }


def control_rows(families: Dict[str, Dict[str, Any]]) -> List[Dict[str, Any]]:
    train_prompts = {q for family in families.values() for q, _ in family["rows"]}
    pool: List[Tuple[str, str, Dict[str, Any]]] = []
    for template in sorted(families):
        family = families[template]
        if family["status"] != "usable":
            continue
        for prompt, gold in family["rows"]:
            pool.append((prompt, gold, family))
    step = max(1, len(pool) // CONTROL_ROWS)
    chosen: List[Dict[str, Any]] = []
    for prompt, gold, family in pool[::step][:CONTROL_ROWS]:
        moved = perturb(prompt, family, BUMP_LADDER, MULTIPLE_LADDER, train_prompts)
        if moved is None:
            continue
        chosen.append({"q": prompt, "gold": gold, "q_cf": moved["q"], "gold_cf": moved["gold"]})
    return chosen


# -- entry points -----------------------------------------------------------
def build_parser() -> argparse.ArgumentParser:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--out-dir", default=str(OUT_DIR))
    ap.add_argument("--plan", action="store_true", help="coverage only: no model, no scores")
    ap.add_argument("--check", default="")
    return ap


def write_report(out_dir: Path, report: Dict[str, Any]) -> Path:
    out_dir.mkdir(parents=True, exist_ok=True)
    path = out_dir / "report.json"
    path.write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return path


def _count(rows: Sequence[Dict[str, Any]], key: str) -> Dict[str, int]:
    out: Dict[str, int] = {}
    for row in rows:
        out[str(row[key])] = out.get(str(row[key]), 0) + 1
    return out


def plan(args: argparse.Namespace) -> Dict[str, Any]:
    train = read_pairs(TRAIN)
    holdout = read_pairs(HOLDOUT)
    families = build_families(train)
    by_status: Dict[str, int] = {}
    for family in families.values():
        by_status[family["status"]] = by_status.get(family["status"], 0) + 1
    selected, dropped = select_rows(holdout, families)
    usable_rows = sum(f["n"] for f in families.values() if f["status"] == "usable")
    report = {
        "stage": "plan",
        "grammar": "92.1",
        "train_rows": len(train),
        "train_digest": rows_digest(train),
        "holdout_rows": len(holdout),
        "holdout_digest": rows_digest(holdout),
        "min_family_rows": MIN_FAMILY_ROWS,
        "families_considered": len(families),
        "families_by_status": by_status,
        "usable_family_rows_in_train": usable_rows,
        "families_fitted": {
            template: {
                "n": family["n"],
                "status": family["status"],
                "expression": family.get("expression"),
                "equivalent": family.get("equivalent"),
                "operands": family.get("operands"),
            }
            for template, family in sorted(families.items())
        },
        "holdout_rows_selected": len(selected),
        "holdout_rows_dropped": dropped,
        "by_expression": _count(selected, "expression"),
        "by_strategy": _count(selected, "strategy"),
    }
    print(
        f"families {len(families)} {by_status} -> usable rows in train {usable_rows}; "
        f"hold-out selected {len(selected)}/{len(holdout)} dropped {dropped}",
        flush=True,
    )
    for expression, count in sorted(_count(selected, "expression").items(), key=lambda kv: -kv[1]):
        print(f"  {expression:20s} {count}", flush=True)
    write_report(Path(args.out_dir), report)
    return report


def run(args: argparse.Namespace) -> Dict[str, Any]:
    train = read_pairs(TRAIN)
    holdout = read_pairs(HOLDOUT)
    families = build_families(train)
    selected, dropped = select_rows(holdout, families)
    control = control_rows(families)
    print(f"selected {len(selected)} hold-out rows, control {len(control)} train rows", flush=True)
    report: Dict[str, Any] = {
        "stage": "scored",
        "grammar": "92.1",
        "train_digest": rows_digest(train),
        "holdout_digest": rows_digest(holdout),
        "selected_digest": hashlib.sha256(
            json.dumps([[row["q"], row["q_cf"]] for row in selected], ensure_ascii=False).encode(
                "utf-8"
            )
        ).hexdigest(),
        "selected": len(selected),
        "dropped": dropped,
        "control": len(control),
        "families_by_status": _count(
            [{"s": family["status"]} for family in families.values()], "s"
        ),
        "runs": [],
    }
    out_dir = Path(args.out_dir)
    started = time.time()
    for kind, seed in ARMS:
        print(f"\n== {kind} seed {seed} ==", flush=True)
        row = run_arm(kind, seed, selected, control)
        print(
            f"   original {row['original']['correct']}/{row['original']['n']}"
            f"  counterfactual {row['counterfactual']['correct']}/{row['counterfactual']['n']}"
            f"  changed {row['answer_changed']['changed']}/{row['answer_changed']['n']}"
            f"  control {row['control_original']['correct']}->{row['control_counterfactual']['correct']}"
            f"  ({row['seconds']}s)",
            flush=True,
        )
        report["runs"].append(row)
        write_report(out_dir, report)
    report["seconds"] = round(time.time() - started, 1)
    report["decision"] = verdict(report["runs"])
    path = write_report(out_dir, report)
    print(f"\nwrote {path}", flush=True)
    print(json.dumps(report["decision"], ensure_ascii=False, indent=2), flush=True)
    return report


def check(report_path: Path) -> Tuple[bool, str]:
    report = json.loads(report_path.read_text(encoding="utf-8"))
    problems: List[str] = []
    if report.get("stage") != "scored":
        return False, "this is a --plan report; there is nothing to check"
    if report["holdout_digest"] != rows_digest(read_pairs(HOLDOUT)):
        problems.append("hold-out rows changed since the run")
    if report["train_digest"] != rows_digest(read_pairs(TRAIN)):
        problems.append("training rows changed since the run")
    families = build_families(read_pairs(TRAIN))
    for run in report["runs"]:
        rows = run["rows"]
        for key, column in (("original", "correct"), ("counterfactual", "correct_cf")):
            got = sum(1 for row in rows if row[column])
            if got != run[key]["correct"]:
                problems.append(f"{run['arm']} seed{run['seed']}: {key} does not recompute")
        changed = sum(1 for row in rows if row["answer"].strip() != row["answer_cf"].strip())
        if changed != run["answer_changed"]["changed"]:
            problems.append(f"{run['arm']} seed{run['seed']}: changed count does not recompute")
        path = REPO_ROOT / run["checkpoint"]
        if not path.is_file():
            problems.append(f"missing checkpoint {run['checkpoint']}")
        elif sha256_file(path) != run["sha256"]:
            problems.append(f"sha256 changed for {run['checkpoint']}")
        for row in rows:
            if row["q"].strip() == row["q_cf"].strip():
                problems.append(f"{run['arm']} seed{run['seed']}: row {row['i']} was not perturbed")
                break
            if str(row["gold"]).strip() == str(row["gold_cf"]).strip():
                problems.append(f"{run['arm']} seed{run['seed']}: row {row['i']} gold unchanged")
                break
            operands = _operands(row)
            expected = evaluate(as_node(row["node"]), operands)
            if expected is None or not base._agrees(expected, str(row["gold_cf"])):
                problems.append(
                    f"{run['arm']} seed{run['seed']}: row {row['i']} gold_cf is not "
                    "what the fitted expression says"
                )
                break
            # every candidate that fits the family's training rows must agree on
            # this test point; otherwise the gold depends on which one was picked
            template = row.get("template") or base.digit_template(row["q"])
            family = families.get(template)
            if family is None or family["status"] != "usable":
                problems.append(
                    f"{run['arm']} seed{run['seed']}: row {row['i']} family no longer fits"
                )
                break
            disagreeing = [
                node
                for node in family["nodes"]
                if evaluate(as_node(node), operands) is None
                or not base._agrees(evaluate(as_node(node), operands), str(row["gold_cf"]))
            ]
            if disagreeing:
                problems.append(
                    f"{run['arm']} seed{run['seed']}: row {row['i']} fits disagree on gold_cf"
                )
                break
    if verdict(report["runs"])["verdict"] != report["decision"]["verdict"]:
        problems.append("decision does not recompute")
    first = report["runs"][0]
    model = load_model(first["arm"], REPO_ROOT / first["checkpoint"])
    rerun = measure_holdout(model, [(row["q"], row["gold"]) for row in first["rows"]])
    differing = sum(1 for a, b in zip(rerun, first["rows"]) if a["answer"] != b["answer"])
    if differing:
        problems.append(f"original answers regenerated differently on {differing} rows")
    if problems:
        return False, "; ".join(problems)
    return True, (
        f"check OK ({len(report['runs'])} arms recomputed, "
        f"{first['arm']} seed{first['seed']} original rows re-run row-for-row)"
    )


def _operands(row: Dict[str, Any]) -> List[float]:
    slots = base.slot_values(row["q_cf"])
    return [
        float(value) for index, value in enumerate(slots) if index not in set(row["constant_slots"])
    ]


def main() -> int:
    args = build_parser().parse_args()
    if args.check:
        ok, message = check(Path(args.check))
        print(message)
        return 0 if ok else 1
    if args.plan:
        plan(args)
        return 0
    run(args)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
